-- Correct and enrich Course 2 Lesson 4: distinguish oblique case from ezafe after -ek.
-- Haig & Öpengin (2018), Table 4 p.172 and Table 8 p.178.
DO $migration$
DECLARE affected integer;
BEGIN
  UPDATE public.lesson_content
  SET content_html = $new$<section class="klesson-card"><h2>١. نادیاری و ناوی بێ نیشانەی دیاریکراو</h2><p>لە کورمانجیی ستاندارددا نادیاریی ناوی تاک بە پاشگری <code>-ek</code> نیشان دەدرێت: <code>gund</code> «گوند» → <code>gund-ek</code> «گوندێک»، <code>jin</code> «ژن» → <code>jin-ek</code> «ژنێک». بە پێچەوانەوە، بۆ دیاریکراوی پاشگری تایبەتی نییە؛ ناوی بێ <code>-ek</code> بە پێی سیاق دەتوانێت واتای دیار یان واتای جۆریی گشتی هەبێت.</p><p>Haig و Öpengin (2018، لاپەڕەی ١٧٢) ئەم جیاوازییە بە نموونە ڕوون دەکەنەوە: <code>hirç hat</code> «ئەو ورچە هات» (دیار)، <code>hirç-ek hat</code> «ورچێک هات» (نادیار)، و <code>vêrê hirç nîne</code> «لێرە ورچ نییە» (گشتی/جۆری).</p></section>
<section class="klesson-card"><h2>٢. حاڵەتی ڕاستەوخۆ و ناڕاستەوخۆ</h2><p>ناوی تاک لە کورمانجیی ستاندارددا دوو حاڵەتی سەرەکی هەیە: ڕاستەوخۆ (Direct) و ناڕاستەوخۆ (Oblique). خشتەی ٤ی Haig و Öpengin (2018، لاپەڕەی ١٧٢) فۆڕمەکانی ناوی نێر و مێ لەگەڵ نادیاری پیشان دەدات:</p><table><thead><tr><th>ڕەگەز</th><th>دیار: ڕاستەوخۆ</th><th>دیار: ناڕاستەوخۆ</th><th>نادیار: ڕاستەوخۆ</th><th>نادیار: ناڕاستەوخۆ</th></tr></thead><tbody><tr><td>نێر</td><td><code>gund</code></td><td><code>gund-î</code></td><td><code>gund-ek</code></td><td><code>gund-ek-î</code></td></tr><tr><td>مێ</td><td><code>jin</code></td><td><code>jin-ê</code></td><td><code>jin-ek</code></td><td><code>jin-ek-ê</code></td></tr></tbody></table><p>ئەم خشتەیە نیشان دەدات کە فۆڕمی حاڵەت بە ڕەگەزی ڕێزمانی و نادیاریی ناوەکە پەیوەستە. لە ناوی نادیاردا <code>-ek</code> نیشانەی نادیارییە و کۆتایییەکانی دوای ئەوە لە فۆڕمی ناڕاستەوخۆدا دەردەکەون.</p></section>
<section class="klesson-card"><h2>٣. جیاوازیی حاڵەت و ئەزافە: هاوشێوەییی فۆڕم، جیاوازیی ئەرک</h2><p>هەمان کۆتاییی ڕووکەشی لە هەموو پێکهاتەیەکدا هەمان ئەرکی ڕێزمانی نییە. ئەم دوو نموونەیە بەراورد بکە:</p><table><thead><tr><th>نموونە</th><th>شیکردنەوە</th><th>واتا</th></tr></thead><tbody><tr><td><code>gund-ek-î</code></td><td>ناوی نێری نادیار + نیشانەی حاڵەتی ناڕاستەوخۆ</td><td>فۆڕمی ناڕاستەوخۆی «گوندێک»</td></tr><tr><td><code>bajar-ek-î mezin</code></td><td><code>-ek</code> نادیاری؛ <code>-î</code> ئەزافەی نێر پێش هاوەڵناو</td><td>شارێکی گەورە</td></tr><tr><td><code>jin-ek-ê</code></td><td>ناوی مێی نادیار + نیشانەی حاڵەتی ناڕاستەوخۆ</td><td>فۆڕمی ناڕاستەوخۆی «ژنێک»</td></tr><tr><td><code>jinek-e</code></td><td>ناوی مێی نادیار + ئەزافەی مێ پێش بەستەری دواتر</td><td>فۆڕمی ئەزافەی «ژنێک»</td></tr></tbody></table><p>خشتەی ٨ی Haig و Öpengin (2018، لاپەڕەی ١٧٨) فۆڕمەکانی ئەزافەی ناوی نادیار بە <code>gundek-î</code> و <code>jinek-e</code> تۆمار دەکات. لە نموونەی <code>bajar-ek-î mezin</code>دا، <code>-î</code> ئەزافەی نێرە؛ بەڵام لە فۆڕمی <code>gund-ek-î</code>ی خشتەی ٤دا، ئەو کۆتایییە نیشانەی حاڵەتی ناڕاستەوخۆی ناوی نێری نادیارە. پێکهاتە و شوێنی وشەکە ئەرکەکە دیاری دەکەن.</p></section>
<section class="klesson-card"><h2>٤. تێبینیی شێوەزار و سنووری یاساکە</h2><p class="klesson-note">Haig و Öpengin (2018، لاپەڕەکانی ١٧٢ و ١٧٨) دەڵێن جیاوازیی ڕەگەز لە فۆڕمی ناڕاستەوخۆ و ئەزافەی دوای <code>-ek</code> لە هەندێک شێوەزاردا لاواز دەبێت؛ هەندێک جار فۆڕمە نێر و مێیەکان تێکەڵ دەبن. بۆیە <code>gund-ek-î</code> و <code>jin-ek-ê</code> وەک فۆڕمەکانی خشتەی ستاندارد فێربە، بەڵام ئەم جیاوازییە بە بێ جیاوازی بۆ هەموو ناوچەکان مەگشتێنە.</p></section>
<section class="klesson-card"><h2>پرسیارەکانی پێداچوونەوە</h2><ol><li>پاشگری <code>-ek</code> چی نیشان دەدات؟</li><li>بۆچی ناوی بێ <code>-ek</code> هەمیشە دیار نییە؟</li><li>لە خشتەی ٤دا فۆڕمی ناڕاستەوخۆی نێری نادیار و مێی نادیار چین؟</li><li>جیاوازیی ئەرکی <code>-î</code> لە <code>gund-ek-î</code> و <code>bajar-ek-î mezin</code> چییە؟</li><li>بۆچی فۆڕمەکانی ئەزافەی دوای <code>-ek</code> دەبێت بە ئاگادارییەوە بگوازرێنەوە بۆ شێوەزارەکان؟</li></ol></section>
<section class="klesson-card"><h2>وەڵامی نموونەیی</h2><ol><li><code>-ek</code> زۆرجار نادیاریی ناوی تاک نیشان دەدات.</li><li>چونکە ناوی بێ نیشانە بە پێی سیاق دەتوانێت واتای دیار یان گشتی هەبێت.</li><li>نێر: <code>gund-ek-î</code>؛ مێ: <code>jin-ek-ê</code>.</li><li>لە <code>gund-ek-î</code>دا <code>-î</code> نیشانەی حاڵەتی ناڕاستەوخۆیە؛ لە <code>bajar-ek-î mezin</code>دا ئەزافەی نێرە کە ناو بە هاوەڵناوەوە دەبەستێتەوە.</li><li>چونکە سەرچاوەکان لاوازبوون و تێکەڵبوونی ڕێککەوتنی ڕەگەز لە هەندێک شێوەزاردا تۆمار دەکەن.</li></ol></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ul><li>Haig, Geoffrey & Ergin Öpengin. (2018). “Kurmanji Kurdish in Turkey: Structure, varieties and status.” pp. 156–214. Table 4, p. 172 (case and indefiniteness); §3.2.2, p. 172 (gender variation); Table 8, p. 178 (ezafe forms). <a href="https://www.uni-bamberg.de/fileadmin/aspra/06_Team/Publications_and_CV/HaigOepengin2018_Kurmanji_Kurdish_.pdf" target="_blank" rel="noopener">PDF — University of Bamberg</a>.</li><li>Haig, Geoffrey. (2018). “Northern Kurdish (Kurmanjî).” In Geoffrey Haig & Geoffrey Khan (eds.), <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. Berlin: De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI: 10.1515/9783110421682-004</a>.</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> Renas Media. <a href="https://kurdishacademy.org/?page_id=623" target="_blank" rel="noopener">پەڕەی کتێب لە ئەکادێمیای کوردی</a>.</li></ul><p class="klesson-note">ئەم فۆڕمانە بۆ کورمانجیی ستانداردن؛ جیاوازییە ناوچەییەکان بە سەرچاوەی تایبەت دیاری کراون.</p></section>$new$,
      updated_at = now()
  WHERE lesson_key = 'kurmanji-course-2-lesson-04.html'
    AND course_id = 'kurmanji-course-2'
    AND content_html = $old$<section class="klesson-card"><h2>١. نادیاری بە -ek</h2><p>لە نمونەی باوی کورمانجی‌دا gund ‘گوند’ و gundek ‘گوندێک’ بەراورد دەکرێن. -ek نیشانەی نادیاریی تاکە؛ لە شیکردنەوەی ورددا پەیویستە فۆڕمی حاڵەتی ڕاستەوخۆ/ناڕاستەوخۆ و ئەزافەش لەبەرچاو بگیرێت.</p></section><section class="klesson-card"><h2>٢. ناوی بێ پاشگر</h2><p>ناوی بێ -ek هەمیشە بە واتای دیار نیە؛ بە پێی سیاق دەتوانێت ئاماژە بە شتێکی ناسراو، جۆرێک بە گشتی، یان شتێک کە لە گفتوگۆدا دیارە بکات. بۆیە پەیویستە ڕستە و سیاق بخوێندرێتەوە.</p></section><section class="klesson-card"><h2>٣. حاڵەت و فۆڕمی نادیار</h2><p>لە ستانداردی کورمانجی‌دا شێوەی ناوی نادیار دەتوانێت لە حاڵەتی ناڕاستەوخۆدا نیشانەی زیاتر وەربگرێت؛ وەک <em>gund-ek-î</em> و <em>jin-ek-ê</em>. لەم فۆڕمانەدا <em>-ek</em> نیشانەی نادیاریی تاکە، و کۆتاییی <em>-î/-ê</em> فۆڕمی حاڵەتی ناڕاستەوخۆی ناوەکە نیشان دەدات. ئەمە لە نمونەی <em>bajar-ek-î mezin</em> جیاوازە: لەو پێکهاتەیەدا <em>-î</em> پەیوەندیی ئەزافە دروست دەکات بۆ بەستنەوەی هاوەڵناوی <em>mezin</em> بە ناوەکە. واتە فۆڕمی ڕووکەشی هاوشێوە هەمیشە ئەرکی ڕێزمانیی یەکسان نیە؛ پێویستە پێکهاتە و سیاق بپشکنرێت.</p></section>
<section class="klesson-card"><h2>تێبینیی مێتۆدی</h2><p class="klesson-note">Haig (2018)، لە بەشی ناوی کورمانجی و خشتەی حاڵەت، جیاوازی حاڵەتی ڕاستەوخۆ/ناڕاستەوخۆ و فۆڕمی ناوی نادیار پیشان دەدات. شێوەی هەر ناوێک بە ڕەگەز، حاڵەت و سیاقەوە پەیوەستە.</p></section>
<section class="klesson-card"><h2>پرسیارەکانی پێداچوونەوە</h2><ol><li>پاشگری -ek زۆرجار چی نیشان دەدات؟</li><li>بۆچی ناوی بێ -ek هەمیشە دیار نیە؟</li><li>چۆن حاڵەت دەتوانێت فۆڕمی ناوی نادیار بگۆڕێت؟</li></ol></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ul><li>Haig, Geoffrey. (2018). “Northern Kurdish (Kurmanjî).” In Geoffrey Haig & Geoffrey Khan (eds.), <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. Berlin: De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI: 10.1515/9783110421682-004</a>.</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> Renas Media. <a href="https://kurdishacademy.org/?page_id=623" target="_blank" rel="noopener">پەڕەی کتێب لە ئەکادێمیای کوردی</a>.</li></ul><p class="klesson-note">نمونە و یاساکان لە چوارچێوەی کورمانجیی ستاندارددا پێشکەش کراون؛ بۆ جیاوازیی شێوەزار و فۆڕمی تایبەت، دەبێت سەرچاوە و سیاق دیاری بکرێن.</p></section>$old$;
  GET DIAGNOSTICS affected = ROW_COUNT;
  IF affected <> 1 THEN
    RAISE EXCEPTION 'Expected exactly one unchanged Course 2 Lesson 4 row; updated % rows', affected;
  END IF;
END
$migration$;
